    private static void testReturnScaleAndInputNotModified() {
        BigDecimal amount = new BigDecimal("200.1234");
        BigDecimal original = new BigDecimal("200.1234");

        BigDecimal delivery = FeeCalculator.deliveryFee(amount, 1);
        BigDecimal service = FeeCalculator.serviceFee(amount);

        assertEquals(2, delivery.scale(), "deliveryFee return scale");
        assertEquals(2, service.scale(), "serviceFee return scale");
        assertEquals(original, amount, "input amount not modified");
        assertEquals(original.scale(), amount.scale(), "input amount scale not modified");
    }

    private static void assertEquals(BigDecimal expected, BigDecimal actual, String message) {
        if (expected.compareTo(actual) != 0) {
            throw new AssertionError(message + " expected=" + expected + " actual=" + actual);
        }
    }

    private static void assertEquals(int expected, int actual, String message) {
        if (expected != actual) {
            throw new AssertionError(message + " expected=" + expected + " actual=" + actual);
        }
    }

    private static void assertEquals(BigDecimal expected, BigDecimal actual, String message, boolean compareScale) {
        if (compareScale) {
            if (!expected.equals(actual)) {
                throw new AssertionError(message + " expected=" + expected + " actual=" + actual);
            }
        } else {
            assertEquals(expected, actual, message);
        }
    }

    private static void assertThrowsIllegalArgumentException(Runnable runnable, String message) {
        try {
            runnable.run();
        } catch (IllegalArgumentException e) {
            return;
        } catch (RuntimeException e) {
            throw new AssertionError(message + " expected IllegalArgumentException but got " + e.getClass().getName(), e);
        }
        throw new AssertionError(message + " expected IllegalArgumentException but nothing was thrown");
    }
