## FeeCalculator.java

```java
import java.math.BigDecimal;
import java.math.RoundingMode;

public final class FeeCalculator {

    private static final BigDecimal ZERO = new BigDecimal("0");
    private static final BigDecimal TWO = new BigDecimal("2");
    private static final BigDecimal FIVE = new BigDecimal("5");
    private static final BigDecimal TWELVE = new BigDecimal("12");
    private static final BigDecimal ONE_HUNDRED = new BigDecimal("100");
    private static final BigDecimal TWO_HUNDRED = new BigDecimal("200");

    private FeeCalculator() {
    }

    /**
     * 配送费：
     * - itemCount == 0：返回 0
     * - itemCount > 0 且 amount > 200：返回 0
     * - 其他合法情况：返回 12
     *
     * 金额单位：元，返回值保留 2 位小数。
     */
    public static BigDecimal deliveryFee(BigDecimal amount, int itemCount) {
        validateAmount(amount);
        validateItemCount(itemCount);

        if (itemCount == 0) {
            return scaleMoney(ZERO);
        }

        if (amount.compareTo(TWO_HUNDRED) > 0) {
            return scaleMoney(ZERO);
        }

        return scaleMoney(TWELVE);
    }

    /**
     * 服务费：
     * - amount == 0：返回 0
     * - 0 < amount <= 100：返回 2
     * - amount > 100：返回 5
     *
     * 金额单位：元，返回值保留 2 位小数。
     */
    public static BigDecimal serviceFee(BigDecimal amount) {
        validateAmount(amount);

        if (amount.compareTo(ZERO) == 0) {
            return scaleMoney(ZERO);
        }

        if (amount.compareTo(ONE_HUNDRED) <= 0) {
            return scaleMoney(TWO);
        }

        return scaleMoney(FIVE);
    }

    private static void validateAmount(BigDecimal amount) {
        if (amount == null) {
            throw new IllegalArgumentException("amount must not be null");
        }
        if (amount.compareTo(ZERO) < 0) {
            throw new IllegalArgumentException("amount must be greater than or equal to 0");
        }
    }

    private static void validateItemCount(int itemCount) {
        if (itemCount < 0) {
            throw new IllegalArgumentException("itemCount must be greater than or equal to 0");
        }
    }

    private static BigDecimal scaleMoney(BigDecimal value) {
        return value.setScale(2, RoundingMode.HALF_UP);
    }
}
